output_text:
[
  {
    "id": "entry_cart_pickup_required",
    "text": "A shopper must first take the cart from the entry cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "carrying_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "carrying_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "Items should not be picked up unless the shopper is currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper should not carry groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_storage": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_after_first_item",
    "text": "Once any required item has been collected, the cart must eventually be returned to the northwest cart return.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return_cell": "at(0,1)",
        "cart_parked_at_northwest_return": "cartAt(0,1)",
        "carrying_cart": "hasCart"
      },
      "events": {
        "collect_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "return_cart_to_northwest": {
          "pre": {
            "and": [
              "northwest_cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_northwest_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item",
      "discharge": "return_cart_to_northwest"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may not exit the supermarket until the cart has been parked at the northwest return point.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_northwest_return": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "premature_exit": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "premature_exit"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "The cart should only be left at the designated northwest cart return cell.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return_cell": "at(0,1)",
        "not_at_cart_return": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_away_from_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_return"
    }
  },
  {
    "id": "cart_no_east_from_west_wall_return_lane",
    "text": "While still pushing the cart on the west-wall return lane, the shopper should not turn east away from the cart return.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "west_wall_return_lane": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "cart_on_west_wall_return_lane": {
          "and": [
            "carrying_cart",
            "west_wall_return_lane"
          ]
        }
      },
      "events": {
        "cart_turns_east_from_west_wall": {
          "pre": {
            "and": [
              "cart_on_west_wall_return_lane",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_turns_east_from_west_wall"
    }
  },
  {
    "id": "cart_shelf_station_no_direct_exit_moves",
    "text": "When pushing the cart at shelf-service stations, the shopper should not take direct exit-oriented moves but should backtrack toward the cart return.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "east_shelf_station": {
          "or": [
            "at(6,4)",
            "at(6,2)"
          ]
        },
        "middle_lower_shelf_station": "at(2,4)",
        "direct_exit_move_from_east_station": {
          "and": [
            "east_shelf_station",
            {
              "or": [
                "E",
                "S"
              ]
            }
          ]
        },
        "direct_exit_move_from_middle_lower_station": {
          "and": [
            "middle_lower_shelf_station",
            "S"
          ]
        }
      },
      "events": {
        "cart_takes_direct_exit_move_from_shelf_station": {
          "pre": {
            "and": [
              "carrying_cart",
              {
                "or": [
                  "direct_exit_move_from_east_station",
                  "direct_exit_move_from_middle_lower_station"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_takes_direct_exit_move_from_shelf_station"
    }
  }
]
